19: 
20: #include "crypt-port.h"
21: 
22: #include <errno.h>
23: #include <stdlib.h>
24: 
25: /* The internal storage area within struct crypt_data is used as
26:    follows.  We don't know what alignment the algorithm modules will
27:    need for their scratch data, so give it the maximum natural
28:    alignment.  Note that the C11 alignas() specifier can't be applied
29:    directly to a struct type, but it can be applied to the first field
30:    of a struct, which effectively forces alignment of the entire
31:    struct, since the first field must always have offset 0.  */
32: struct crypt_internal
33: {
34:   /* Alignment critical data members.  */
35:   char alignas (alignof (max_align_t)) alg_specific[ALG_SPECIFIC_SIZE];
36:   /* Not alignment critical data members.  */
37:   char output[CRYPT_OUTPUT_SIZE];
38: };
39: 
40: static_assert(sizeof (struct crypt_internal) + alignof (struct crypt_internal)
41:               <= CRYPT_DATA_INTERNAL_SIZE,
42:               "crypt_data.internal is too small for crypt_internal");
43: 
44: /* struct crypt_data is allocated by application code and contains
45:    only char-typed fields, so its 'internal' field may not be
46:    sufficiently aligned.  */
47: static inline struct crypt_internal *
48: get_internal (struct crypt_data *data)
49: {
50:   uintptr_t internalp = (uintptr_t) data->internal;
51:   const uintptr_t align = alignof (struct crypt_internal);
52:   internalp = (internalp + align - 1) & ~(align - 1);
