static void
write_table_u8(size_t m, size_t n, const uint8_t *tbl, const char *name)
{
  printf("\nconst uint8_t %s[%zu][%zu] = {\n", name, m, n);
  for (size_t i = 0; i < m; i++)
    {
      fputs("  {", stdout);
      for (size_t j = 0; j < n; j++)
        {
          if (j % 12 == 0)
            fputs("\n   ", stdout);
          printf(" 0x%02x,", (unsigned int)tbl[i*n + j]);
        }
      puts("\n  },");
    }
  puts("};");
}
